function reportDateValue(v){return String(v||"").slice(0,10)}
function reportInRange(v,from,to){const d=reportDateValue(v);return !!d&&(!from||d>=from)&&(!to||d<=to)}
function renderSupplierReport(){
 const from=$id("reportDateFrom").value,to=$id("reportDateTo").value;
 if(from&&to&&from>to){$id("supplierReportTotals").innerHTML='<div class="empty-suppliers">تاريخ البداية يجب أن يسبق تاريخ النهاية.</div>';$id("supplierReportRows").innerHTML="";return}
 const invoices=state.purchaseInvoices.filter(x=>reportInRange(x.date||x.createdAt,from,to));
 const returns=state.supplierReturns.filter(r=>r.status!=="void"&&reportInRange(r.date||r.createdAt,from,to));
 const currencies=new Set(),totals={},supplierRows={};
 const getTotal=c=>totals[c]||(totals[c]={purchases:0,returns:0,paid:0,returnCredits:0,due:0,credit:0});
 const getSupplier=(id,name,c)=>{const key=id+"|"+c;return supplierRows[key]||(supplierRows[key]={supplierId:id,name:name||"مورد",currency:c,purchases:0,returns:0,paid:0,returnCredits:0,due:0,credit:0})};
 // Purchases and current balances belong to invoices dated within the selected period.
 invoices.forEach(x=>{
  const c=x.currency||"SYP",s=state.suppliers.find(v=>v.id===x.supplierId),t=getTotal(c),row=getSupplier(x.supplierId,s?.name,c);
  const net=Math.max(0,(Number(x.total)||0)-(Number(x.returnedTotal)||0));
  const paid=Math.max(0,Number(x.paid)||0),due=Math.max(0,Number(x.due)||0),credit=invoiceCreditAvailable(x);
  currencies.add(c);t.purchases+=Number(x.total)||0;t.due+=due;t.credit+=credit;
  row.purchases+=Number(x.total)||0;row.due+=due;row.credit+=credit;
 });
 // Returns are counted by the date they were actually recorded.
 returns.forEach(r=>{
  const c=r.currency||"SYP",s=state.suppliers.find(v=>v.id===r.supplierId),t=getTotal(c),row=getSupplier(r.supplierId,s?.name,c),amount=Number(r.amount)||0;
  currencies.add(c);t.returns+=amount;t.returnCredits+=amount;row.returns+=amount;row.returnCredits+=amount;
 });
 // Cash payments are period transactions, even when they settle an older invoice.
 state.purchaseInvoices.forEach(x=>{
  const c=x.currency||"SYP",s=state.suppliers.find(v=>v.id===x.supplierId);
  const cashPayments=(Array.isArray(x.payments)?x.payments:[]).filter(p=>p.kind!=="return");
  let recordedCash=0;
  cashPayments.forEach(p=>{
   const amount=Number(p.amount)||0;recordedCash+=amount;
   if(reportInRange(p.date||x.date||x.createdAt,from,to)){
    const t=getTotal(c),row=getSupplier(x.supplierId,s?.name,c);currencies.add(c);t.paid+=amount;row.paid+=amount;
   }
  });
  // Legacy invoices may have a paid amount without a corresponding payment-history entry.
  const missingCash=Math.max(0,(Number(x.paid)||0)-recordedCash);
  if(missingCash>0&&reportInRange(x.date||x.createdAt,from,to)){
   const t=getTotal(c),row=getSupplier(x.supplierId,s?.name,c);currencies.add(c);t.paid+=missingCash;row.paid+=missingCash;
  }
 });
 const participating=new Set(Object.keys(supplierRows).map(k=>k.slice(0,k.lastIndexOf("|"))));
 const countHtml='<div class="report-count-card"><span>فواتير الشراء</span><b>'+invoices.length+'</b></div><div class="report-count-card"><span>المرتجعات</span><b>'+returns.length+'</b></div><div class="report-count-card"><span>الموردون</span><b>'+participating.size+'</b></div>';
 $id("reportCounts").innerHTML=countHtml;
 $id("supplierReportTotals").innerHTML=currencies.size?[...currencies].sort().map(c=>{const t=totals[c],net=t.purchases-t.returns;return '<article class="report-currency-card"><h3>'+cur(c)+'</h3><div class="report-metrics"><div><small>إجمالي المشتريات</small><b>'+fmt(t.purchases)+'</b></div><div><small>قيمة المرتجعات</small><b class="balance-due">− '+fmt(t.returns)+'</b></div><div><small>صافي المشتريات</small><b>'+fmt(net)+'</b></div><div><small>الدفعات النقدية خلال الفترة</small><b class="balance-paid">'+fmt(t.paid)+'</b></div><div><small>المرتجعات كتسويات دائنة</small><b class="balance-paid">'+fmt(t.returnCredits)+'</b></div><div><small>إجمالي التسويات الدائنة</small><b class="balance-paid">'+fmt(t.paid+t.returnCredits)+'</b></div><div><small>المتبقي الحالي لفواتير الفترة</small><b class="balance-due">'+fmt(t.due)+'</b></div><div><small>الرصيد الدائن لنا على فواتير الفترة</small><b class="balance-paid">'+fmt(t.credit)+'</b></div></div></article>'}).join(""):'<div class="empty-suppliers">لا توجد حركات مالية ضمن الفترة المحددة.</div>';
 const rows=Object.values(supplierRows).sort((a,b)=>a.name.localeCompare(b.name,"ar"));
 $id("supplierReportRows").innerHTML=rows.length?'<div class="supplier-report-cards">'+rows.map(r=>'<article class="supplier-report-card"><div class="supplier-report-card-head"><b>'+esc(r.name)+'</b><span>'+cur(r.currency)+'</span></div><button type="button" class="outline supplier-report-open" data-view-statement="'+esc(r.supplierId)+'">فتح ملف المورد</button><div class="supplier-report-card-metrics"><span>المشتريات <b>'+fmt(r.purchases)+'</b></span><span>المرتجعات <b>'+fmt(r.returns)+'</b></span><span>الدفعات النقدية <b>'+fmt(r.paid)+'</b></span><span>المرتجعات الدائنة <b>'+fmt(r.returnCredits)+'</b></span><span>إجمالي التسويات <b>'+fmt(r.paid+r.returnCredits)+'</b></span><span>المتبقي الحالي <b class="'+(r.due>0?"balance-due":"balance-paid")+'">'+fmt(r.due)+'</b></span><span>رصيد دائن لنا <b class="balance-paid">'+fmt(r.credit)+'</b></span></div></article>').join("")+'</div>':'<div class="empty-suppliers">لا توجد بيانات لعرضها.</div>';
}
function setReportMonth(){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1);$id("reportDateFrom").value=first.getFullYear()+"-"+String(first.getMonth()+1).padStart(2,"0")+"-"+String(first.getDate()).padStart(2,"0");$id("reportDateTo").value=now.getFullYear()+"-"+String(now.getMonth()+1).padStart(2,"0")+"-"+String(now.getDate()).padStart(2,"0");renderSupplierReport()}
function renderStatement(id){
const s=state.suppliers.find(x=>x.id===id);if(!s)return;statementSupplierId=id;
const invoices=state.purchaseInvoices.filter(x=>x.supplierId===id);invoices.forEach(ensurePaymentHistory);
$id("statementTitle").textContent="كشف حساب: "+s.name;
const totals={};
invoices.forEach(x=>{const c=x.currency||"SYP";if(!totals[c])totals[c]={purchases:0,paid:0,due:0,credit:0};totals[c].purchases+=Math.max(0,Number(x.total)-Number(x.returnedTotal||0));totals[c].paid+=Number(x.paid)||0;totals[c].due+=Number(x.due)||0;totals[c].credit+=invoiceCreditAvailable(x)});
$id("statementSummary").innerHTML=Object.entries(totals).length?Object.entries(totals).map(([c,t])=>'<div class="statement-currency"><h3>'+cur(c)+'</h3><div class="statement-metrics"><div><small>صافي المشتريات</small><b>'+fmt(t.purchases)+'</b></div><div><small>إجمالي المدفوع</small><b>'+fmt(t.paid)+'</b></div><div><small>المستحق للمورد</small><b class="'+(t.due>0?"balance-due":"balance-paid")+'">'+fmt(t.due)+'</b></div><div><small>رصيد دائن لنا</small><b class="balance-paid">'+fmt(t.credit)+'</b></div></div></div>').join(""):'<div class="empty-suppliers">لا توجد حركات مالية لهذا المورد بعد.</div>';
const ledger=[];invoices.forEach(x=>{ledger.push({date:x.date||x.createdAt,type:"فاتورة شراء",description:"فاتورة "+(x.invoiceNo||x.id)+" · "+(x.materialName||"مادة")+" · المتبقي "+fmt(x.due)+" "+cur(x.currency),amount:Number(x.total)||0,currency:x.currency||"SYP",kind:"invoice"});if(Number(x.due)>0.00001)ledger.push({date:x.date||x.createdAt,type:"مبلغ مستحق للمورد",description:"المتبقي من فاتورة "+(x.invoiceNo||x.id),amount:Number(x.due)||0,currency:x.currency||"SYP",kind:"debt"});const creditBalance=invoiceCreditAvailable(x);if(creditBalance>0.00001)ledger.push({date:x.date||x.createdAt,type:"مبلغ مستحق لنا لدى المورد",description:"رصيد دائن من فاتورة "+(x.invoiceNo||x.id)+" · يمكن استرداده أو تسويته",amount:creditBalance,currency:x.currency||"SYP",kind:"credit"});ensurePaymentHistory(x).forEach(p=>ledger.push({date:p.date||x.date||x.createdAt,type:p.kind==="initial"?"دفعة عند تسجيل الفاتورة":"تسديد للمورد",description:"فاتورة "+(x.invoiceNo||x.id)+(p.reason?" · "+p.reason:""),amount:Number(p.amount)||0,currency:p.currency||x.currency||"SYP",kind:"payment"}));activeInvoiceReturns(x.id).forEach(r=>ledger.push({date:r.date||r.createdAt,type:"دفعة عينية · مرتجع مشتريات",description:"فاتورة "+(x.invoiceNo||x.id)+" · "+fmt(r.quantity)+" "+r.unit+" · "+(r.reason||""),amount:Number(r.amount)||0,currency:r.currency||x.currency||"SYP",kind:"return"}));state.supplierRecoveries.filter(r=>r.invoiceId===x.id&&r.status!=="void").forEach(r=>ledger.push({date:r.date,type:"استرداد نقدي من المورد",description:"استرداد مستحقات الفاتورة "+(x.invoiceNo||x.id),amount:Number(r.amount)||0,currency:r.currency||x.currency||"SYP",kind:"recovery"}));creditApplicationsTo(x.id).forEach(r=>ledger.push({date:r.date,type:"استخدام مستحقات سابقة",description:"تسوية من مستحقات فاتورة "+(r.sourceInvoiceNo||r.sourceInvoiceId)+" على فاتورة "+(x.invoiceNo||x.id),amount:Number(r.amount)||0,currency:r.currency||x.currency||"SYP",kind:"applicationIn"}));creditApplicationsFrom(x.id).forEach(r=>{const target=state.purchaseInvoices.find(v=>v.id===r.targetInvoiceId);ledger.push({date:r.date,type:"تحويل مستحقات إلى فاتورة أخرى",description:"استخدام من رصيد هذه الفاتورة لتسوية فاتورة "+(target?.invoiceNo||r.targetInvoiceNo||r.targetInvoiceId),amount:Number(r.amount)||0,currency:r.currency||x.currency||"SYP",kind:"applicationOut"})})});
ledger.sort((a,b)=>new Date(b.date)-new Date(a.date));
$id("supplierProfileContent").innerHTML=ledger.length?'<div class="statement-ledger-head"><h3>سجل الحركات المالية</h3><span>'+ledger.length+' حركة</span></div>'+ledger.map(x=>{const category=x.kind==="invoice"?"invoice":x.kind==="debt"?"debt":x.kind==="credit"?"credit":x.kind==="payment"?"payment":x.kind==="return"?"return":(x.kind==="recovery"||x.kind==="applicationIn"||x.kind==="applicationOut"?"settlement":"other");return '<article class="statement-entry" data-profile-kind="'+category+'"><div><b>'+esc(x.type)+'</b><small>'+esc(x.description)+'</small><small>'+esc(new Date(x.date).toLocaleString("ar-SY"))+'</small></div><b class="'+(x.kind==="payment"||x.kind==="return"||x.kind==="recovery"||x.kind==="applicationIn"||x.kind==="credit"?"balance-paid":"balance-due")+'">'+(x.kind==="payment"||x.kind==="return"||x.kind==="applicationIn"?"− ":"+ ")+fmt(x.amount)+' '+cur(x.currency)+'</b></article>'}).join(""):'<div class="empty-suppliers">لا توجد فواتير أو دفعات مسجلة لهذا المورد.</div>';document.querySelectorAll("[data-profile-tab]").forEach(b=>b.classList.toggle("active",b.dataset.profileTab==="all"));
tab("statement");
}
function renderSuppliers(){ $id("supplierCount").textContent=state.suppliers.length;const q=norm($id("supplierSearch").value);const visible=state.suppliers.filter(s=>!q||norm([s.name,s.phone,s.contact,s.address].join(" ")).includes(q));$id("suppliersList").innerHTML=visible.length?visible.map(s=>{const invoices=state.purchaseInvoices.filter(x=>x.supplierId===s.id),currencies=[...new Set(invoices.map(x=>x.currency||"SYP"))],dueByCurrency={},creditByCurrency={},returns=state.supplierReturns.filter(r=>r.supplierId===s.id&&r.status!=="void").length;invoices.forEach(x=>{const currency=x.currency||"SYP";dueByCurrency[currency]=(dueByCurrency[currency]||0)+(Number(x.due)||0);creditByCurrency[currency]=(creditByCurrency[currency]||0)+invoiceCreditAvailable(x)});const dueText=Object.entries(dueByCurrency).filter(([,v])=>v>0.00001).map(([k,v])=>fmt(v)+" "+cur(k)).join(" · ")||"0",creditText=Object.entries(creditByCurrency).filter(([,v])=>v>0.00001).map(([k,v])=>fmt(v)+" "+cur(k)).join(" · ")||"0";return '<article class="supplier-row supplier-profile-card"><div class="supplier-profile-main"><b>'+esc(s.name)+'</b><small>'+esc(s.phone||"لا يوجد هاتف")+' · '+esc(s.contact||"")+'</small><small>'+esc(s.address||"")+'</small><div class="supplier-card-metrics"><span>الفواتير <b>'+invoices.length+'</b></span><span>المرتجعات <b>'+returns+'</b></span><span>الديون <b>'+dueText+'</b></span><span>مستحقاتنا <b>'+creditText+'</b></span></div></div><div class="supplier-actions"><button type="button" class="primary" data-view-statement="'+esc(s.id)+'">فتح ملف المورد</button><button type="button" data-edit-supplier="'+esc(s.id)+'">تعديل</button><button type="button" data-delete-supplier="'+esc(s.id)+'">حذف</button></div></article>'}).join(""):'<div class="empty-suppliers">لا يوجد موردون مسجلون. أضف أول مورد للبدء.</div>';supplierSelect.innerHTML='<option value="">اختر المورد</option>'+state.suppliers.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join("");populateSupplierFilters();}
function renderMaterials(){materialSelect.innerHTML='<option value="">اختر المادة</option>'+state.rawMaterials.map(m=>'<option value="'+esc(m.id)+'">'+esc(m.name)+' ('+esc(m.unit)+')</option>').join("");renderReturnOptions();}
function renderReturnOptions(){if(!returnInvoiceSelect)return;const eligible=state.purchaseInvoices.filter(x=>Number(x.quantity)-Number(x.returnedQuantity||0)>0.00001);returnInvoiceSelect.innerHTML='<option value="">اختر فاتورة قابلة للإرجاع</option>'+eligible.map(x=>{const s=state.suppliers.find(v=>v.id===x.supplierId);return '<option value="'+esc(x.id)+'">'+esc(s?.name||"مورد")+' · فاتورة '+esc(x.invoiceNo||x.id)+' · '+esc(x.materialName)+' · المتاح: '+fmt(Number(x.quantity)-Number(x.returnedQuantity||0))+' '+esc(x.unit)+'</option>'}).join("");renderReturnPreview();}
function renderReturnPreview(){if(!rf)return;const f=new FormData(rf),x=state.purchaseInvoices.find(v=>v.id===f.get("invoiceId")),q=Number(f.get("quantity"))||0;if(!x||q<=0){$id("returnPreview").textContent="اختر فاتورة وأدخل الكمية لعرض قيمة المرتجع.";return}const unitPrice=Number(x.unitPrice)||Number(x.total)/Math.max(Number(x.quantity),0.000001);$id("returnPreview").textContent="قيمة المرتجع التقديرية: "+fmt(q*unitPrice)+" "+cur(x.currency)+" · الكمية المتبقية القابلة للإرجاع: "+fmt(Number(x.quantity)-Number(x.returnedQuantity||0))+" "+x.unit;}
function renderReturns(){if(!rf)return;const active=state.supplierReturns.filter(r=>r.status!=="void");$id("returnCount").textContent=active.length;const q=norm($id("returnSearch").value),from=$id("returnDateFrom").value,to=$id("returnDateTo").value;const filtered=state.supplierReturns.filter(r=>{const s=state.suppliers.find(v=>v.id===r.supplierId);return (!q||norm([s?.name,r.supplierName,r.invoiceNo,r.invoiceId,r.materialName,r.reason,r.voidReason].join(" ")).includes(q))&&inDateRange(r.date,from,to)&&($id("returnSupplierFilter").value==="all"||r.supplierId===$id("returnSupplierFilter").value)&&($id("returnCurrencyFilter").value==="all"||(r.currency||"SYP")===$id("returnCurrencyFilter").value)&&($id("returnStatusFilter").value==="all"||($id("returnStatusFilter").value==="void"?r.status==="void":r.status!=="void"))});$id("returnsList").innerHTML=filtered.length?[...filtered].sort((a,b)=>new Date(b.date)-new Date(a.date)).map(r=>{const s=state.suppliers.find(v=>v.id===r.supplierId),voided=r.status==="void";return '<article data-supplier-id="'+esc(r.supplierId)+'" data-supplier-name="'+esc(s?.name||"مورد")+'" class="invoice-row return-row '+(voided?"return-void":"")+'"><div><b>'+esc(s?.name||"مورد")+(voided?' <span class="return-void-label">ملغى</span>':'')+'</b><small>فاتورة '+esc(r.invoiceNo||r.invoiceId)+' · '+esc(r.materialName)+' · '+fmt(r.quantity)+' '+esc(r.unit)+'</small><small>'+esc(r.date)+' · '+esc(r.reason)+'</small>'+(voided?'<small>سبب الإلغاء: '+esc(r.voidReason||"—")+'</small>':'')+'</div><div><b class="'+(voided?"muted":"balance-paid")+'">'+(voided?"ملغى · ":"− ")+fmt(r.amount)+' '+cur(r.currency)+'</b>'+(voided?"":'<button type="button" class="outline return-cancel-btn" data-cancel-return="'+esc(r.id)+'">إلغاء المرتجع</button>')+'</div></article>'}).join(""):'<div class="empty-suppliers">لا توجد مرتجعات مسجلة حتى الآن.</div>';renderReturnOptions();groupSupplierRecords("returnsList");}

function ensurePaymentHistory(x){x.payments=Array.isArray(x.payments)?x.payments:[];const recorded=x.payments.filter(p=>p.kind!=="return").reduce((sum,p)=>sum+(Number(p.amount)||0),0);const unrecorded=Number((Number(x.paid||0)-recorded).toFixed(2));if(unrecorded>0.00001)x.payments.unshift({amount:unrecorded,date:x.date||x.createdAt||new Date().toISOString(),currency:x.currency,kind:"initial"});return x.payments.filter(p=>p.kind!=="return");}
function paymentHistoryMarkup(x){
 const payments=ensurePaymentHistory(x).map((p,i)=>({...p,entryType:"payment",label:p.kind==="initial"?"الدفعة عند تسجيل الفاتورة":"دفعة تسديد "+(i+1)}));
 const returns=activeInvoiceReturns(x.id).map(r=>({amount:r.amount,currency:r.currency,date:r.date||r.createdAt,reason:r.reason,entryType:"return",label:"دفعة عينية (مرتجع مواد) · "+fmt(r.quantity)+" "+r.unit}));
 const applications=creditApplicationsTo(x.id).map(r=>({amount:r.amount,currency:r.currency,date:r.date,entryType:"application",label:"تسوية من مستحقات فاتورة "+(r.sourceInvoiceNo||r.sourceInvoiceId)}));
 const entries=[...payments,...returns,...applications].sort((a,b)=>new Date(a.date)-new Date(b.date));
 if(!entries.length)return '<div class="payment-history empty-payment-history">لا توجد دفعات أو مرتجعات أو تسويات مسجلة على هذه الفاتورة.</div>';
 return '<details class="payment-history"><summary>سجل الدفعات والمرتجعات والتسويات <span>'+entries.length+'</span></summary><div class="payment-history-list">'+entries.map(p=>'<div class="payment-history-item"><span>'+esc(p.label)+'</span><b>'+(p.entryType==="return"||p.entryType==="application"?"− ":"")+fmt(p.amount)+' '+cur(p.currency||x.currency)+'</b><small>'+esc(new Date(p.date||x.date||x.createdAt).toLocaleString("ar-SY"))+(p.reason?" · "+esc(p.reason):"")+'</small></div>').join("")+'</div></details>';
}
function renderInvoices(){
 const all=[...state.purchaseInvoices].sort((a,b)=>new Date(b.date||b.createdAt)-new Date(a.date||a.createdAt)),q=norm($id("invoiceSearch").value),status=$id("invoiceStatus").value,from=$id("invoiceDateFrom").value,to=$id("invoiceDateTo").value;
 const list=all.filter(x=>{const supplier=state.suppliers.find(v=>v.id===x.supplierId),due=Number(x.due)>0.00001,returned=Number(x.returnedQuantity)>0;return (!q||norm([supplier?.name,x.invoiceNo,x.id,x.materialName].join(" ")).includes(q))&&inDateRange(x.date||x.createdAt,from,to)&&($id("invoiceSupplierFilter").value==="all"||x.supplierId===$id("invoiceSupplierFilter").value)&&($id("invoiceCurrencyFilter").value==="all"||(x.currency||"SYP")===$id("invoiceCurrencyFilter").value)&&(status==="all"||(status==="due"&&due)||(status==="paid"&&!due)||(status==="returned"&&returned))});
 $id("invoiceCount").textContent=all.length;$id("invoiceSummary").textContent=list.length+" من "+all.length+" فاتورة";
 $id("invoicesList").innerHTML=list.length?list.map(x=>{
  const supplier=state.suppliers.find(v=>v.id===x.supplierId),net=Math.max(0,Number(x.total)-Number(x.returnedTotal||0)),applied=creditApplicationsTo(x.id).reduce((n,r)=>n+(Number(r.amount)||0),0),availableCredit=invoiceCreditAvailable(x);
  return '<article class="invoice-row invoice-register-card" data-supplier-id="'+esc(x.supplierId)+'" data-supplier-name="'+esc(supplier?.name||"مورد محذوف")+'"><div class="invoice-register-details"><b class="invoice-register-title">فاتورة '+esc(x.invoiceNo||x.id)+'</b><small>المورد: '+esc(supplier?.name||"مورد محذوف")+'</small><small>المادة: '+esc(x.materialName)+'</small><small>الكمية: '+fmt(x.quantity)+' '+esc(x.unit)+'</small><small>التاريخ: '+esc(x.date||"—")+'</small><small>إجمالي الفاتورة: '+fmt(x.total)+' '+cur(x.currency)+'</small><small>صافي الفاتورة: '+fmt(net)+' '+cur(x.currency)+'</small>'+(Number(x.returnedQuantity)>0?'<small class="balance-paid">الكمية المرتجعة: '+fmt(x.returnedQuantity)+' '+esc(x.unit)+'</small><small class="balance-paid">قيمة المرتجع: '+fmt(x.returnedTotal)+' '+cur(x.currency)+'</small>':'')+'</div><div class="invoice-register-payment"><b>المدفوع نقداً: '+fmt(x.paid)+' '+cur(x.currency)+'</b>'+(applied>0?'<small class="balance-paid">مستحقات سابقة مستخدمة: '+fmt(applied)+' '+cur(x.currency)+'</small>':'')+'<small class="'+(x.due>0?"balance-due":"balance-paid")+'">'+(x.due>0?"المتبقي: "+fmt(x.due)+" "+cur(x.currency):"لا يوجد دين مستحق")+'</small>'+(availableCredit>0?'<small class="balance-paid">مستحقات متبقية لنا: '+fmt(availableCredit)+' '+cur(x.currency)+'</small>':'')+(x.due>0?'<button type="button" class="primary debt-pay-btn" data-pay-invoice="'+esc(x.id)+'">تسجيل دفعة</button>':'')+'</div>'+paymentHistoryMarkup(x)+'</article>';
 }).join(""):'<div class="empty-suppliers">لا توجد فواتير شراء مسجلة بعد.</div>';
 renderDebts();renderReturns();renderSupplierCredits();
groupSupplierRecords("invoicesList");}
function renderDebts(){const allUnpaid=state.purchaseInvoices.filter(x=>Number(x.due)>0.00001);const q=norm($id("debtSearch").value),from=$id("debtDateFrom").value,to=$id("debtDateTo").value;const unpaid=allUnpaid.filter(x=>{const s=state.suppliers.find(v=>v.id===x.supplierId);return (!q||norm([s?.name,x.invoiceNo,x.id,x.materialName].join(" ")).includes(q))&&inDateRange(x.date||x.createdAt,from,to)&&($id("debtSupplierFilter").value==="all"||x.supplierId===$id("debtSupplierFilter").value)&&($id("debtCurrencyFilter").value==="all"||(x.currency||"SYP")===$id("debtCurrencyFilter").value)}).sort((a,b)=>new Date(a.date||a.createdAt)-new Date(b.date||b.createdAt));$id("debtCount").textContent=allUnpaid.length;const totals={};unpaid.forEach(x=>{totals[x.currency]=(totals[x.currency]||0)+Number(x.due)});$id("debtTotals").innerHTML=Object.keys(totals).length?Object.entries(totals).map(([c,n])=>'<span class="debt-total">'+fmt(n)+' '+cur(c)+'</span>').join(""):'<span class="muted">لا توجد مبالغ مستحقة</span>';$id("debtsList").innerHTML=unpaid.length?unpaid.map(x=>{const s=state.suppliers.find(v=>v.id===x.supplierId);return '<article class="invoice-row debt-row" data-supplier-id="'+esc(x.supplierId)+'" data-supplier-name="'+esc(s?.name||"مورد محذوف")+'"><div><b>'+esc(s?.name||"مورد محذوف")+'</b><small>فاتورة '+esc(x.invoiceNo||x.id)+' · '+esc(x.materialName)+' · '+esc(x.date||"")+'</small><small>الإجمالي: '+fmt(x.total)+' '+cur(x.currency)+' · المدفوع: '+fmt(x.paid)+' '+cur(x.currency)+'</small></div><div><b class="balance-due">المتبقي: '+fmt(x.due)+' '+cur(x.currency)+'</b><button type="button" class="primary debt-pay-btn" data-pay-invoice="'+esc(x.id)+'">تسجيل دفعة</button></div>'+paymentHistoryMarkup(x)+'</article>'}).join(""):'<div class="empty-suppliers">رائع! لا توجد ديون مستحقة للموردين حالياً.</div>';groupSupplierRecords("debtsList");}
function renderSupplierCredits(){
 const all=state.purchaseInvoices.map(x=>{
  const records=state.supplierReturns.filter(r=>r.invoiceId===x.id),returned=Math.max(0,records.length?records.filter(r=>r.status!=="void").reduce((n,r)=>n+(Number(r.amount)||0),0):(Number(x.returnedTotal)||0)),net=Math.max(0,(Number(x.total)||0)-returned),paid=Math.max(0,Number(x.paid)||0),recovered=state.supplierRecoveries.filter(r=>r.invoiceId===x.id&&r.status!=="void").reduce((n,r)=>n+(Number(r.amount)||0),0),applied=creditApplicationsFrom(x.id).reduce((n,r)=>n+(Number(r.amount)||0),0),appliedIn=creditApplicationsTo(x.id).reduce((n,r)=>n+(Number(r.amount)||0),0),creditAmount=Number(Math.max(0,paid+appliedIn-net-recovered-applied).toFixed(2));
  return {...x,creditAmount,netAmount:net,returnedAmount:returned,recoveredAmount:recovered,appliedAmount:applied};
 }).filter(x=>x.creditAmount>0.00001||x.recoveredAmount>0.00001||x.appliedAmount>0.00001);
 const q=norm($id("creditSearch").value),from=$id("creditDateFrom").value,to=$id("creditDateTo").value;
 const rows=all.filter(x=>{const s=state.suppliers.find(v=>v.id===x.supplierId);return (!q||norm([s?.name,x.invoiceNo,x.id,x.materialName].join(" ")).includes(q))&&inDateRange(x.date||x.createdAt,from,to)&&($id("creditSupplierFilter").value==="all"||x.supplierId===$id("creditSupplierFilter").value)&&($id("creditCurrencyFilter").value==="all"||(x.currency||"SYP")===$id("creditCurrencyFilter").value)}).sort((a,b)=>new Date(b.date||b.createdAt)-new Date(a.date||a.createdAt));
 $id("creditCount").textContent=all.filter(x=>x.creditAmount>0.00001).length;
 const totals={};rows.forEach(x=>{const c=x.currency||"SYP";totals[c]=(totals[c]||0)+x.creditAmount});
 $id("creditTotals").innerHTML=Object.keys(totals).length?Object.entries(totals).map(([c,n])=>'<span class="debt-total">'+fmt(n)+' '+cur(c)+'</span>').join(""):'<span class="muted">لا توجد مستحقات لنا</span>';
 $id("creditsList").innerHTML=rows.length?rows.map(x=>{const supplier=state.suppliers.find(v=>v.id===x.supplierId),applications=creditApplicationsFrom(x.id);return '<article class="invoice-row supplier-credit-row" data-supplier-id="'+esc(x.supplierId)+'" data-supplier-name="'+esc(supplier?.name||"مورد محذوف")+'"><div><b>'+esc(supplier?.name||"مورد محذوف")+'</b><small>فاتورة المصدر: '+esc(x.invoiceNo||x.id)+'</small><small>المادة: '+esc(x.materialName||"—")+'</small><small>التاريخ: '+esc(x.date||"—")+'</small><small>صافي الفاتورة: '+fmt(x.netAmount)+' '+cur(x.currency)+'</small><small>ما دفعناه: '+fmt(x.paid)+' '+cur(x.currency)+'</small><small>استرددناه نقداً: '+fmt(x.recoveredAmount)+' '+cur(x.currency)+'</small><small>استخدمناه في فواتير جديدة: '+fmt(x.appliedAmount)+' '+cur(x.currency)+'</small>'+applications.map(r=>{const target=state.purchaseInvoices.find(v=>v.id===r.targetInvoiceId);return '<small class="balance-paid">تسوية إلى فاتورة '+esc(target?.invoiceNo||r.targetInvoiceNo||r.targetInvoiceId)+' · '+fmt(r.amount)+' '+cur(r.currency||x.currency)+' · '+esc(new Date(r.date).toLocaleDateString("ar-SY"))+'</small>'}).join("")+'</div><div><b class="balance-paid">المتبقي لنا: '+fmt(x.creditAmount)+' '+cur(x.currency)+'</b>'+(x.creditAmount>0?'<button type="button" class="primary supplier-recovery-btn" data-recover-supplier-credit="'+esc(x.id)+'">تسجيل استرداد نقدي</button>':'')+'</div></article>'}).join(""):'<div class="empty-suppliers">لا توجد مبالغ مستحقة لنا لدى الموردين حالياً.</div>';
groupSupplierRecords("creditsList");}
function recoverSupplierCredit(invoiceId){
 const x=state.purchaseInvoices.find(v=>v.id===invoiceId);if(!x)return;
 const records=state.supplierReturns.filter(r=>r.invoiceId===x.id),returned=records.length?records.filter(r=>r.status!=="void").reduce((n,r)=>n+(Number(r.amount)||0),0):(Number(x.returnedTotal)||0);
 const remaining=invoiceCreditAvailable(x);
 if(remaining<=0)return alert("لا يوجد مبلغ متبقٍ لاسترداده من المورد.");
 const raw=prompt("أدخل المبلغ الذي استلمناه فعلياً من المورد. المستحق المتبقي: "+fmt(remaining)+" "+cur(x.currency));
 if(raw===null)return;
 const amount=Number(String(raw).replace(/,/g,""));
 if(!Number.isFinite(amount)||amount<=0||amount>remaining+0.00001)return alert("أدخل مبلغاً صحيحاً لا يتجاوز المستحق المتبقي.");
 const received=Number(Math.min(amount,remaining).toFixed(2));
 if(!confirm("تأكيد تسجيل استرداد نقدي بقيمة "+fmt(received)+" "+cur(x.currency)+" من المورد؟"))return;
 state.supplierRecoveries.unshift({id:"rec_"+Date.now()+"_"+Math.random().toString(36).slice(2,7),invoiceId:x.id,supplierId:x.supplierId,invoiceNo:x.invoiceNo||x.id,amount:received,currency:x.currency||"SYP",date:new Date().toISOString(),status:"active"});
 save();renderSupplierCredits();if(statementSupplierId===x.supplierId){const p=document.querySelector('[data-panel="statement"]');if(p&&!p.classList.contains("is-hidden"))renderStatement(statementSupplierId)}
 alert("تم تسجيل المبلغ المسترد وتخفيض مستحقاتنا لدى المورد.");
}
$id("creditsList").addEventListener("click",e=>{const b=e.target.closest("[data-recover-supplier-credit]");if(b)recoverSupplierCredit(b.dataset.recoverSupplierCredit)});
function creditApplicationsFrom(invoiceId){return state.supplierCreditApplications.filter(r=>r.sourceInvoiceId===invoiceId&&r.status!=="void");}
function creditApplicationsTo(invoiceId){return state.supplierCreditApplications.filter(r=>r.targetInvoiceId===invoiceId&&r.status!=="void");}
function invoiceCreditAvailable(x){
 const records=state.supplierReturns.filter(r=>r.invoiceId===x.id),returned=records.length?records.filter(r=>r.status!=="void").reduce((n,r)=>n+(Number(r.amount)||0),0):(Number(x.returnedTotal)||0),net=Math.max(0,(Number(x.total)||0)-returned),appliedIn=creditApplicationsTo(x.id).reduce((n,r)=>n+(Number(r.amount)||0),0),gross=Math.max(0,(Number(x.paid)||0)+appliedIn-net),recovered=state.supplierRecoveries.filter(r=>r.invoiceId===x.id&&r.status!=="void").reduce((n,r)=>n+(Number(r.amount)||0),0),applied=creditApplicationsFrom(x.id).reduce((n,r)=>n+(Number(r.amount)||0),0);
 return Number(Math.max(0,gross-recovered-applied).toFixed(2));
}
function availableSupplierCredit(supplierId,currency){
 return Number(state.purchaseInvoices.filter(x=>x.supplierId===supplierId&&(x.currency||"SYP")===currency).reduce((n,x)=>n+invoiceCreditAvailable(x),0).toFixed(2));
}
function activeInvoiceReturns(invoiceId){return state.supplierReturns.filter(r=>r.invoiceId===invoiceId&&r.status!=="void");}
function syncInvoiceReturns(x){const records=state.supplierReturns.filter(r=>r.invoiceId===x.id);if(records.length){const active=records.filter(r=>r.status!=="void");x.returnedQuantity=Number(active.reduce((n,r)=>n+(Number(r.quantity)||0),0).toFixed(3));x.returnedTotal=Number(active.reduce((n,r)=>n+(Number(r.amount)||0),0).toFixed(2));}else{x.returnedQuantity=Number(x.returnedQuantity)||0;x.returnedTotal=Number(x.returnedTotal)||0;}return x;}
function recalculateInvoiceBalance(x){syncInvoiceReturns(x);const net=Math.max(0,Number(x.total)-Number(x.returnedTotal||0)),applied=creditApplicationsTo(x.id).reduce((n,r)=>n+(Number(r.amount)||0),0);x.due=Number(Math.max(0,net-Number(x.paid||0)-applied).toFixed(2));x.supplierCredit=Number(Math.max(0,Number(x.paid||0)+applied-net).toFixed(2));}
function payInvoice(id){const x=state.purchaseInvoices.find(v=>v.id===id);if(!x||Number(x.due)<=0)return;const raw=prompt('المبلغ المراد دفعه للمورد. المتبقي: '+fmt(x.due)+' '+cur(x.currency));if(raw===null)return;const amount=Number(String(raw).replace(/,/g,''));if(!Number.isFinite(amount)||amount<=0||amount>x.due+0.00001)return alert('أدخل مبلغاً صحيحاً لا يتجاوز المتبقي.');const paidNow=Number(Math.min(amount,x.due).toFixed(2));x.paid=Number((Number(x.paid)+paidNow).toFixed(2));recalculateInvoiceBalance(x);x.payments=Array.isArray(x.payments)?x.payments:[];x.payments.push({amount:paidNow,date:new Date().toISOString(),currency:x.currency});save();renderInvoices();alert('تم تسجيل الدفعة بنجاح. المتبقي: '+fmt(x.due)+' '+cur(x.currency));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pay-invoice]');if(b)payInvoice(b.dataset.payInvoice)});
